-- =====================================================================
-- SEED: consumo real de chopp por bar/dia (MEEP) — até a data do relatório
-- Gerado da consolidação dos 18 .xls (dedup + nomes corrigidos).
-- Idempotente (ON CONFLICT). Resolve bar_id por nome quando existir.
-- =====================================================================
ON CONFLICT (bar_nome, data, marca) DO UPDATE SET barris = EXCLUDED.barris, bar_id = COALESCE(public.meep_consumo_bar.bar_id, EXCLUDED.bar_id);
